(()=>{
const blocked=/save|publish|upload|delete|remove|create|send|confirm|cancel|add product|add customer|add section|duplicate|apply|reset|enable|disable/i;
const nativeFetch=window.fetch.bind(window);window.fetch=(input,init={})=>{const method=(init.method||(input instanceof Request?input.method:'GET')).toUpperCase();if(!['GET','HEAD','OPTIONS'].includes(method))return Promise.resolve(new Response(JSON.stringify({error:'View-only access: changes are disabled.'}),{status:403,headers:{'Content-Type':'application/json'}}));return nativeFetch(input,init)};
function update(){document.querySelectorAll('button,input[type="submit"],input[type="file"]').forEach(el=>{if(el.matches('input[type="submit"],input[type="file"]')||blocked.test(el.textContent||el.value||'')||el.id==='quick-actions'){el.disabled=true;el.title='View-only access';}});document.querySelectorAll('[contenteditable="true"]').forEach(el=>el.contentEditable='false');document.querySelectorAll('a[href*="signout-with-chatgpt"]').forEach(a=>a.href='/admin/logout');}
function start(){const banner=document.createElement('div');banner.textContent='View-only access · Saving, uploads and publishing are disabled.';banner.setAttribute('role','status');banner.style.cssText='position:sticky;top:0;z-index:99999;background:#fff3cd;color:#664d03;padding:10px 20px;text-align:center;font:14px system-ui';document.body.prepend(banner);update();new MutationObserver(update).observe(document.body,{childList:true,subtree:true});document.addEventListener('submit',e=>{e.preventDefault();alert('This account has view-only access.');},true);}
document.readyState==='loading'?document.addEventListener('DOMContentLoaded',start):start();
})();
